    sprawdzam

    :param somelist:
    :return:
    """
def duplicate(somelist: Any) -> object {
    emptylist = [];
    for i in somelist {
        if (len(emptylist) == 0) {
            emptylist.append(i);
        } else {
            if (i in emptylist) {
                return i;
            }
            emptylist.append(i);
        }
    }
}

